"""
Module for the qBraid environment configuration schema.

"""

import logging
from typing import Optional

from pydantic import (
    BaseModel,
    ConfigDict,
    field_serializer,
    field_validator,
    model_validator,
)
from pydantic.alias_generators import to_camel

from qbraid_core.system.versions import is_valid_semantic_version, package_has_match_on_pypi

logger = logging.getLogger(__name__)


class EnvironmentConfig(BaseModel):
    """Model for the qBraid environment configuration."""

    model_config = ConfigDict(
        alias_generator=to_camel,
        populate_by_name=True,
        from_attributes=True,
        extra="forbid",
    )

    name: str
    description: Optional[str] = None
    tags: Optional[list[str]] = None

    # Provider name for logo lookup (e.g., "ibm", "nvidia", "google")
    # Resolved to URLs via provider API (GET /providers)
    logo: Optional[str] = None

    python_version: Optional[str] = None
    platform: Optional[str] = None  # e.g., "linux-x86_64", "darwin-arm64"
    kernel_name: Optional[str] = None
    shell_prompt: Optional[str] = None
    python_packages: Optional[dict[str, str]] = None  # code request param
    visibility: str = "private"
    group_slug: Optional[str] = None  # Environment group to add this environment to

    # Validation control - set to True to validate packages exist on PyPI
    validate_pypi: bool = False

    @field_validator("python_version")
    @classmethod
    def _check_python_version(cls, value: Optional[str]):
        if value is None:
            return value

        # Sanitize: strip whitespace and remove "Python " prefix if present
        value = value.strip()
        if value.lower().startswith("python "):
            value = value[7:]

        if not value.startswith("3."):
            raise ValueError("Python version must start with 3.")

        if not is_valid_semantic_version(value):
            raise ValueError("Python version must be a valid semantic version")

        # Store only major.minor (e.g., "3.11" not "3.11.7")
        # Compatibility is determined by major.minor; patch versions are interchangeable
        parts = value.split(".")
        if len(parts) >= 2:
            value = f"{parts[0]}.{parts[1]}"

        return value

    @classmethod
    def parse_version_specifier(cls, version: str) -> tuple[str, str]:
        """Parse the version specifier.

        Args:
            version (str): The version string.

        Returns:
            tuple[str, str]: The operator and version number.
        """
        operators = ["==", ">=", "<=", ">", "<", "~="]
        for op in operators:
            if version.startswith(op):
                return op, version[len(op) :]
        return "", version

    @model_validator(mode="after")
    def _check_package_versions(self) -> "EnvironmentConfig":
        """Validate python_packages. PyPI validation only runs if validate_pypi=True."""
        if self.python_packages is None:
            return self

        validated_packages = {}
        for name, version in self.python_packages.items():
            operator, version_number = self.parse_version_specifier(version)

            # Always validate version format if provided
            if version_number and not is_valid_semantic_version(version_number):
                raise ValueError(
                    f"Invalid package '{name}{version}'. "
                    "Version must be a valid combination of a binary op and semantic version x.y.z"
                )

            # Only check PyPI if explicitly requested
            if self.validate_pypi:
                if not package_has_match_on_pypi(name, operator, version_number):
                    raise ValueError(f"Package '{name}' 'v{version_number}' not found on PyPI")

            if operator == "" and version:  # default case
                version = f"=={version}"
            validated_packages[name] = version

        # Update the packages with validated versions
        object.__setattr__(self, "python_packages", validated_packages)
        return self

    @field_serializer("python_packages")
    @classmethod
    def _serialize_package_versions(cls, value: Optional[dict[str, str]]):
        if value is None:
            return value
        # add the python packages as a newline separated string of packages
        return "\n".join(f"{name}{version}" for name, version in value.items())

    @field_serializer("tags")
    @classmethod
    def _serialize_tags(cls, value: Optional[list[str]]):
        if value is None:
            return value

        # TODO: update to return a list of tags and conform with API spec
        return ",".join(value)
